import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { map, catchError, tap } from 'rxjs/operators';
import { environment } from '../../environments/environment';

export interface Sentencia {
  sentencia_id: number;
  conciliacion_id: number;
  fecha_sentencia: string;
  tipo_resolucion: string;
  contenido?: string;
  estado_ejecucion: string;
  institucion_remitida_id?: number;
  observaciones?: string;
  fecha_creacion: string;
  excede_competencias?: boolean;  // 👈 Agregar
  motivo_excede_competencias?: string;  // 👈 Agregar

  // Relaciones
  conciliacion?: {
    conciliacion_id: number;
    denuncia_id: number;
    fecha_audiencia: string;
    resultado_final: string;
    denuncia?: {
      denuncia_id: number;
      numero_expediente: string;
      codigo_externo: string;
      descripcion: string;
      persona?: {
        nombres: string;
        apellidos: string;
      }
    }
  };
  institucion_remitida?: {
    institucion_id: number;
    nombre: string;
  };

  // Para UI (calculados)
  tiene_contenido?: boolean;
  estado_ejecucion_texto?: string;
  denuncia_codigo?: string;
  denuncia_descripcion?: string;
  conciliacion_info?: string;
}

export interface CreateSentenciaDTO {
  conciliacion_id: number;
  fecha_sentencia: string;
  tipo_resolucion: string;
  contenido: string;
  estado_ejecucion: string;
  institucion_remitida_id?: number;
  observaciones?: string;
}

export interface UpdateSentenciaDTO {
  fecha_sentencia?: string;
  tipo_resolucion?: string;
  contenido?: string;
  estado_ejecucion?: string;
  institucion_remitida_id?: number;
  observaciones?: string;
}

export interface SentenciaStats {
  por_estado: Record<string, number>;
  por_mes: Array<{ mes: string; total: number }>;
  total: number;
  pendientes: number;
  ejecutadas: number;
}

@Injectable({
  providedIn: 'root'
})
export class SentenciaService {
  private apiUrl = `${environment.apiUrl}`;

  constructor(private http: HttpClient) {}

  /**
   * Listar sentencias con filtros
   */
  listarSentencias(filtros?: {
    conciliacion_id?: number;
    estado_ejecucion?: string;
    fecha_desde?: string;
    fecha_hasta?: string;
    institucion_id?: number;
    page?: number;
    per_page?: number;
  }): Observable<{ data: Sentencia[]; meta: any }> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== undefined && value !== null && value !== '') {
          params = params.set(key, value.toString());
        }
      });
    }

    return this.http.get<any>(`${this.apiUrl}/sentencias`, { params }).pipe(
      tap(response => console.log('📥 Sentencias recibidas:', response)),
      map(response => {
        if (response.success && response.data) {
          // Procesar cada sentencia para agregar datos de UI
          const data = response.data.map((sentencia: any) => this.procesarSentencia(sentencia));
          return {
            data,
            meta: response.meta || {
              current_page: 1,
              last_page: 1,
              per_page: filtros?.per_page || 15,
              total: data.length
            }
          };
        }
        return { data: [], meta: { total: 0 } };
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener una sentencia por ID
   */
  obtenerSentencia(id: number): Observable<Sentencia> {
    return this.http.get<any>(`${this.apiUrl}/sentencias/${id}`).pipe(
      tap(response => console.log(`📥 Sentencia ${id} recibida:`, response)),
      map(response => {
        if (response.success && response.data) {
          return this.procesarSentencia(response.data);
        }
        throw new Error('Sentencia no encontrada');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Crear nueva sentencia
   */
  crearSentencia(dto: CreateSentenciaDTO): Observable<Sentencia> {
    console.log('📤 Creando sentencia:', dto);

    return this.http.post<any>(`${this.apiUrl}/sentencias`, dto).pipe(
      tap(response => console.log('📥 Respuesta creación sentencia:', response)),
      map(response => {
        if (response.success && response.data) {
          return this.procesarSentencia(response.data);
        }
        throw new Error(response.message || 'Error al crear sentencia');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Actualizar sentencia
   */
  actualizarSentencia(id: number, dto: UpdateSentenciaDTO): Observable<Sentencia> {
    console.log('📤 Actualizando sentencia:', { id, dto });

    return this.http.put<any>(`${this.apiUrl}/sentencias/${id}`, dto).pipe(
      tap(response => console.log('📥 Respuesta actualización sentencia:', response)),
      map(response => {
        if (response.success && response.data) {
          return this.procesarSentencia(response.data);
        }
        throw new Error(response.message || 'Error al actualizar sentencia');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Eliminar sentencia
   */
  eliminarSentencia(id: number): Observable<boolean> {
    return this.http.delete<any>(`${this.apiUrl}/sentencias/${id}`).pipe(
      map(response => response.success),
      catchError(this.handleError)
    );
  }

  /**
   * Cambiar estado de ejecución
   */
  cambiarEstadoEjecucion(id: number, estado: string, observaciones?: string): Observable<Sentencia> {
    return this.http.patch<any>(`${this.apiUrl}/sentencias/${id}/cambiar-estado`, {
      estado_ejecucion: estado,
      observaciones
    }).pipe(
      map(response => {
        if (response.success && response.data) {
          return this.procesarSentencia(response.data);
        }
        throw new Error(response.message || 'Error al cambiar estado');
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener estadísticas
   */
  obtenerEstadisticas(): Observable<SentenciaStats> {
    return this.http.get<any>(`${this.apiUrl}/sentencias/estadisticas`).pipe(
      map(response => {
        if (response.success && response.data) {
          return response.data;
        }
        return {
          por_estado: {},
          por_mes: [],
          total: 0,
          pendientes: 0,
          ejecutadas: 0
        };
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Procesar sentencia para UI
   */
  private procesarSentencia(sentencia: any): Sentencia {
    // Extraer información de denuncia
    let denunciaCodigo = '';
    let denunciaDescripcion = '';
    let conciliacionInfo = '';

    if (sentencia.conciliacion) {
      conciliacionInfo = `CONC-${sentencia.conciliacion.conciliacion_id}`;

      if (sentencia.conciliacion.denuncia) {
        denunciaCodigo = sentencia.conciliacion.denuncia.numero_expediente ||
                        sentencia.conciliacion.denuncia.codigo_externo ||
                        `DEN-${sentencia.conciliacion.denuncia.denuncia_id}`;
        denunciaDescripcion = sentencia.conciliacion.denuncia.descripcion || '';
      }
    }

    return {
      ...sentencia,
      tiene_contenido: !!sentencia.contenido,
      estado_ejecucion_texto: this.getEstadoEjecucionTexto(sentencia.estado_ejecucion),
      denuncia_codigo: denunciaCodigo,
      denuncia_descripcion: denunciaDescripcion,
      conciliacion_info: conciliacionInfo
    };
  }

  /**
   * Obtener texto legible para estado de ejecución
   */
  private getEstadoEjecucionTexto(estado: string): string {
    const estados: Record<string, string> = {
      'PENDIENTE': 'Pendiente de Ejecución',
      'EN_EJECUCION': 'En Ejecución',
      'EJECUTADA': 'Ejecutada',
      'PARCIALMENTE_EJECUTADA': 'Parcialmente Ejecutada',
      'SUSPENDIDA': 'Suspendida',
      'ARCHIVADA': 'Archivada'
    };
    return estados[estado] || estado;
  }

  private handleError(error: any): Observable<never> {
    console.error('Error en SentenciaService:', error);
    let errorMessage = 'Error en la operación';

    if (error.error instanceof ErrorEvent) {
      errorMessage = `Error: ${error.error.message}`;
    } else if (error.error?.message) {
      errorMessage = error.error.message;
    } else if (error.status === 404) {
      errorMessage = 'Recurso no encontrado';
    } else if (error.status === 422) {
      errorMessage = error.error?.message || 'Error de validación';
    }

    return throwError(() => new Error(errorMessage));
  }
}
